/**
 * B5 / BORNTOWIN5 — Cloudflare D1 Server Adapter (`server.js`)
 * Scope: B5 Level Tracking only (Magizh Shopping is not integrated).
 *
 * Connects directly to the Cloudflare D1 database `b5-level-tracking` via the
 * Worker binding `DB` (`env.DB`) and routes all API operations through
 * `src/b5-engine.js` + `src/d1-repository.js`.
 * Does NOT use local JSON files (`db.json`) or in-memory storage as the permanent database.
 */

const express = require('express');
const fs = require('fs');
const os = require('os');
const path = require('path');
const zlib = require('zlib');
const Module = require('module');
const nodemailer = require('nodemailer');

// Self-healing fallback archive for AIC Cloud / GitHub flat, nested, or read-only container deployments
const EMBEDDED_SRC_MODULES_GZ = {
  "d1-node-binding.js": "",
  "d1-repository.js": "",
  "b5-engine.js": ""
};

const _inMemoryModuleCache = {};

function ensureProjectModulesAvailable() {
  const targetDirs = [
    path.join(__dirname, 'src'),
    path.join(os.tmpdir(), 'b5-src-modules')
  ];

  for (const [fileName, gzBase64] of Object.entries(EMBEDDED_SRC_MODULES_GZ)) {
    const srcTarget = path.join(__dirname, 'src', fileName);
    const rootTarget = path.join(__dirname, fileName);
    const nestedSrcTarget = path.join(__dirname, 'BORNTOWIN5', 'src', fileName);
    const nestedRootTarget = path.join(__dirname, 'BORNTOWIN5', fileName);

    const existingSource = [srcTarget, rootTarget, nestedSrcTarget, nestedRootTarget].find(p => fs.existsSync(p));
    const payloadBuf = existingSource
      ? (() => { try { return fs.readFileSync(existingSource); } catch (_) { return null; } })()
      : (() => { try { return zlib.gunzipSync(Buffer.from(gzBase64, 'base64')); } catch (_) { return null; } })();

    if (!payloadBuf) continue;

    for (const dir of targetDirs) {
      const dest = path.join(dir, fileName);
      if (fs.existsSync(dest)) continue;
      try {
        fs.mkdirSync(dir, { recursive: true });
        fs.writeFileSync(dest, payloadBuf);
      } catch (_) {}
    }
  }
}

ensureProjectModulesAvailable();

function findCaseInsensitiveFile(dirPath, targetFileName) {
  try {
    if (!fs.existsSync(dirPath)) return null;
    const lowerTarget = String(targetFileName || '').toLowerCase();
    const entries = fs.readdirSync(dirPath);
    const match = entries.find(e => e.toLowerCase() === lowerTarget);
    return match ? path.join(dirPath, match) : null;
  } catch (_) {
    return null;
  }
}

function loadEmbeddedModuleInMemory(modName) {
  const cleanFile = String(modName || '').replace(/\.js$/i, '') + '.js';
  if (_inMemoryModuleCache[cleanFile]) {
    return _inMemoryModuleCache[cleanFile].exports;
  }
  const gzBase64 = EMBEDDED_SRC_MODULES_GZ[cleanFile];
  if (!gzBase64) {
    throw new Error(`Unknown B5 module: ${cleanFile}`);
  }
  const code = zlib.gunzipSync(Buffer.from(gzBase64, 'base64')).toString('utf8');
  const virtualFilename = path.join(__dirname, 'src', cleanFile);
  const m = new Module(virtualFilename, module);
  m.filename = virtualFilename;
  m.paths = Module._nodeModulePaths(path.join(__dirname, 'src')).concat(Module._nodeModulePaths(__dirname));
  _inMemoryModuleCache[cleanFile] = m;

  const origRequire = m.require.bind(m);
  m.require = function (id) {
    const normalized = String(id || '').replace(/\\/g, '/');
    if (normalized.endsWith('/d1-repository') || normalized.endsWith('/d1-repository.js')) {
      return requireProjectModule('d1-repository');
    }
    if (normalized.endsWith('/d1-node-binding') || normalized.endsWith('/d1-node-binding.js')) {
      return requireProjectModule('d1-node-binding');
    }
    if (normalized.endsWith('/b5-engine') || normalized.endsWith('/b5-engine.js')) {
      return requireProjectModule('b5-engine');
    }
    return origRequire(id);
  };

  m._compile(code, virtualFilename);
  m.loaded = true;
  return m.exports;
}

function requireProjectModule(modName) {
  const cleanName = String(modName || '').replace(/\.js$/i, '');
  const fileName = `${cleanName}.js`;
  const candidateDirs = [
    path.join(__dirname, 'src'),
    __dirname,
    path.join(__dirname, 'BORNTOWIN5', 'src'),
    path.join(__dirname, 'BORNTOWIN5'),
    path.join(process.cwd(), 'src'),
    process.cwd(),
    path.join(process.cwd(), 'BORNTOWIN5', 'src'),
    path.join(process.cwd(), 'BORNTOWIN5'),
    path.join(os.tmpdir(), 'b5-src-modules')
  ];

  for (const dir of candidateDirs) {
    const exactPath = path.join(dir, fileName);
    const resolvedPath = fs.existsSync(exactPath)
      ? exactPath
      : findCaseInsensitiveFile(dir, fileName);
    if (resolvedPath && fs.existsSync(resolvedPath)) {
      try {
        return require(resolvedPath);
      } catch (_) {}
    }
  }

  return loadEmbeddedModuleInMemory(cleanName);
}

const { getD1Binding, createPortableNodeD1Binding } = requireProjectModule('d1-node-binding');
const {
  ensureD1SchemaAndBootstrap,
  loadStateFromD1,
  buildSnapshotMap,
  commitStateToD1
} = requireProjectModule('d1-repository');
const {
  handleApiRequest,
  createSessionContext
} = requireProjectModule('b5-engine');

const app = express();

// AIC Cloud SMTP configuration (credentials supplied only through environment variables)
const SMTP_HOST = process.env.SMTP_HOST || 'mail.aiccloud.in';
const SMTP_PORT = Number(process.env.SMTP_PORT || 587);
const SMTP_USER = process.env.SMTP_USER || 'notifications@borntowin5.com';
const SMTP_PASS = process.env.SMTP_PASS || '';
const EMAIL_FROM = process.env.EMAIL_FROM || SMTP_USER;

const mailer = SMTP_PASS
  ? nodemailer.createTransport({
      host: SMTP_HOST,
      port: SMTP_PORT,
      secure: false,
      requireTLS: true,
      auth: { user: SMTP_USER, pass: SMTP_PASS }
    })
  : null;

async function smtpSender({ to, subject, text, html }) {
  if (!mailer) throw new Error('SMTP_PASS is not configured');
  return mailer.sendMail({
    from: EMAIL_FROM,
    to,
    subject,
    text,
    html: html || undefined
  });
}

app.use(express.json({ limit: '15mb' }));
app.use(express.urlencoded({ extended: true, limit: '15mb' }));

// Block direct web access to internal server/database/configuration files
app.use((req, res, next) => {
  const p = String(req.path || '').toLowerCase();
  if (
    p === '/db.json' ||
    p.endsWith('/db.json') ||
    p.endsWith('.sqlite') ||
    p.endsWith('.d1.json') ||
    p === '/server.js' ||
    p === '/worker.js' ||
    p === '/b5-engine.js' ||
    p === '/d1-repository.js' ||
    p === '/d1-node-binding.js' ||
    p === '/package.json' ||
    p === '/package-lock.json' ||
    p === '/wrangler.toml' ||
    p.startsWith('/.env') ||
    p.startsWith('/.wrangler') ||
    p.startsWith('/src/') ||
    p.startsWith('/migrations/') ||
    p.startsWith('/data/') ||
    p.startsWith('/_backups/')
  ) {
    return res.status(403).json({ error: 'Forbidden: Direct access to internal system files is blocked.' });
  }
  next();
});

function sendPortalFile(res, fileName) {
  const candidates = [
    path.join(__dirname, fileName),
    path.join(__dirname, 'public', fileName),
    path.join(__dirname, 'BORNTOWIN5', fileName),
    path.join(__dirname, 'BORNTOWIN5', 'public', fileName),
    path.join(process.cwd(), fileName),
    path.join(process.cwd(), 'public', fileName)
  ];
  for (const candidate of candidates) {
    if (fs.existsSync(candidate)) {
      return res.sendFile(candidate);
    }
  }
  return res.status(404).send(`Portal file not found: ${fileName}`);
}

// Static portal HTML routes (Emerald Sovereign UI preserved)
app.get('/', (req, res) => sendPortalFile(res, 'member.html'));
app.get('/member.html', (req, res) => sendPortalFile(res, 'member.html'));
app.get('/user/login', (req, res) => sendPortalFile(res, 'login.html'));
app.get('/user/dashboard', (req, res) => sendPortalFile(res, 'member.html'));
app.get('/admin.html', (req, res) => sendPortalFile(res, 'admin.html'));
app.get('/admin/login', (req, res) => sendPortalFile(res, 'admin.html'));
app.get('/admin', (req, res) => sendPortalFile(res, 'admin.html'));
app.get('/login.html', (req, res) => sendPortalFile(res, 'login.html'));
app.get('/leveltrack-admin.html', (req, res) => sendPortalFile(res, 'leveltrack-admin.html'));
app.get('/leveltrack-member.html', (req, res) => sendPortalFile(res, 'leveltrack-member.html'));
app.get('/mobile-preview', (req, res) => sendPortalFile(res, 'mobile-preview.html'));

let d1DatabaseBinding = null;
let d1ConnectionMode = 'uninitialized';

// Delegate all /api/* routes to the Cloudflare Worker D1 Engine (`env.DB`)
app.use('/api', async (req, res) => {
  try {
    if (!d1DatabaseBinding) {
      return res.status(503).json({ error: 'Cloudflare D1 database binding (DB -> b5-level-tracking) is initializing.' });
    }
    const env = {
      ...process.env,
      DB: d1DatabaseBinding
    };
    const result = await handleApiRequest({
      method: req.method,
      pathname: req.originalUrl.split('?')[0],
      query: req.query || {},
      headers: req.headers || {},
      body: req.body || {},
      env,
      smtpSender: SMTP_PASS ? smtpSender : null
    });

    if (result.headers) {
      for (const [k, v] of Object.entries(result.headers)) {
        res.setHeader(k, v);
      }
    }

    if (result.isBinary && Buffer.isBuffer(result.body)) {
      return res.status(result.status || 200).send(result.body);
    }
    return res.status(result.status || 200).json(result.body);
  } catch (err) {
    console.error('B5 D1 API error:', err);
    return res.status(500).json({ error: err?.message || 'Internal Server Error' });
  }
});

// Static assets (CSS, logos, videos) from root, ./public, or nested ./BORNTOWIN5
const staticDirs = [
  __dirname,
  path.join(__dirname, 'public'),
  path.join(__dirname, 'BORNTOWIN5'),
  path.join(__dirname, 'BORNTOWIN5', 'public')
];
for (const dir of staticDirs) {
  if (fs.existsSync(dir)) {
    app.use(express.static(dir));
  }
}

const PORT = process.env.PORT || 10000;

async function startServer() {
  const configuredAdminPwd =
    process.env.B5_ADMIN_PASSWORD ||
    (String(process.env.B5_LOCAL_TEST_ONLY || '') === '1' ? 'ADMIN' : null);

  // SAFETY: Never switch to a blank local/portable database when Remote D1 fails.
  // Doing so makes the Admin portal look empty and can create a second, unrelated dataset.
  // Keep the app unavailable until the configured Cloudflare D1 connection succeeds.
  const { DB: d1, mode } = await getD1Binding({
    persistDir: process.env.B5_D1_PERSIST_DIR || process.env.D1_PERSIST_DIR || undefined
  });
  d1DatabaseBinding = d1;
  d1ConnectionMode = mode;
  try {
    await ensureD1SchemaAndBootstrap(d1DatabaseBinding, configuredAdminPwd);
  } catch (initErr) {
    console.error('REMOTE D1 INITIALIZATION FAILED — no local fallback will be used:', initErr?.stack || initErr?.message || initErr);
    throw new Error(`Cloudflare D1 initialization failed (${d1ConnectionMode}). Check AIC Cloud outbound access, CLOUDFLARE_ACCOUNT_ID, CLOUDFLARE_API_TOKEN permissions, and CLOUDFLARE_D1_DATABASE_ID. Original error: ${initErr?.message || initErr}`);
  }

  // Only seed explicit safe-test-mode records when both B5_SENIORITY_TEST_MODE=1 and B5_LOCAL_TEST_ONLY=1
  if (
    String(process.env.B5_SENIORITY_TEST_MODE || '') === '1' &&
    String(process.env.B5_LOCAL_TEST_ONLY || '') === '1'
  ) {
    const state = await loadStateFromD1(d1DatabaseBinding, configuredAdminPwd);
    const snap = buildSnapshotMap(state);
    const ctx = createSessionContext(state, process.env, SMTP_PASS ? smtpSender : null);
    ctx.seedSeniorityTestDataIntoState();
    await commitStateToD1(d1DatabaseBinding, snap, state, []);
  }

  app.listen(PORT, '0.0.0.0', () => {
    console.log(
      `BORNTOWIN5 running on ${PORT} [Database: Cloudflare D1 (b5-level-tracking) | Binding: DB | Mode: ${d1ConnectionMode}]`
    );
  });
}

startServer().catch(err => {
  console.error('CLOUDFLARE D1 STARTUP FAILED:', err.message);
  process.exit(1);
});
